## Scenario YAML Compiler — YAML → .feature conversion
## Reads YAML scenario files from data/scenarios/ and generates
## .feature files in tests/gateway/ with AUTOGENERATED header + source_hash.
## Exit 1 if any generated file's source_hash mismatches (immutability violation).

import core/trusted/layer_declaration
axiomLayer "tools"
import std/[os, strutils, algorithm]
import checksums/sha1

const
  scenarioDir = "data/scenarios"
  outputDir = "tests/gateway"
  autoHeader = "# AUTOGENERATED — DO NOT EDIT MANUALLY"
  hashPrefix = "# source_hash: "

proc computeHash(content: string): string =
  ## Compute SHA1 hash of content for immutability verification.
  result = $secureHash(content)

proc compileScenario(yamlPath: string): string =
  ## Convert a YAML scenario file to .feature format.
  ## Returns the .feature content as a string.
  let content = readFile(yamlPath)
  let lines = content.splitLines()
  var feature: seq[string] = @[]
  let baseName = yamlPath.extractFilename().changeFileExt("")

  feature.add(autoHeader)
  feature.add(hashPrefix & computeHash(content))
  feature.add("")

  # Parse simple YAML structure: feature name from first non-comment line
  var featureName = baseName.replace("_", " ").replace("-", " ")
  for line in lines:
    let stripped = line.strip()
    if stripped.startsWith("feature:"):
      featureName = stripped.split(':', 1)[1].strip().strip(chars = {'"', '\''})
      break

  feature.add("Feature: " & featureName)
  feature.add("")

  # Extract scenarios and steps
  var inScenario = false
  for line in lines:
    let stripped = line.strip()
    if stripped.startsWith("scenario:"):
      inScenario = true
      let scenarioName = stripped.split(':', 1)[1].strip().strip(chars = {'"', '\''})
      feature.add("  Scenario: " & scenarioName)
      continue
    if inScenario and stripped.startsWith("- step:"):
      let stepName = stripped.split(':', 1)[1].strip().strip(chars = {'"', '\''})
      feature.add("    Given " & stepName)
      continue
    if inScenario and (stripped.startsWith("Given ") or stripped.startsWith("When ") or
                       stripped.startsWith("Then ") or stripped.startsWith("And ")):
      feature.add("    " & stripped)
      continue
    if stripped.startsWith("scenario:") or stripped.len == 0:
      if inScenario and stripped.len == 0:
        inScenario = false
        feature.add("")

  result = feature.join("\n") & "\n"

proc verifyImmutability(featurePath: string, yamlPath: string): bool =
  ## Check if existing .feature file matches the YAML source hash.
  ## Returns true if file is up-to-date or doesn't exist yet.
  if not fileExists(featurePath):
    return true
  let existing = readFile(featurePath)
  let yamlContent = readFile(yamlPath)
  let expectedHash = computeHash(yamlContent)
  for line in existing.splitLines():
    if line.startsWith(hashPrefix):
      let currentHash = line[hashPrefix.len .. ^1]
      return currentHash == expectedHash
  # No hash found — needs regeneration
  return false

proc main() =
  if not dirExists(scenarioDir):
    echo "OK: No scenario directory found (", scenarioDir, ")"
    quit(0)

  var compiled = 0
  var violations = 0

  for path in walkDirRec(scenarioDir, yieldFilter = {pcFile}):
    if not path.endsWith(".yaml"):
      continue
    let baseName = path.extractFilename().changeFileExt("")
    let outputPath = outputDir / baseName & "_generated.feature"

    # Check immutability first
    if fileExists(outputPath) and not verifyImmutability(outputPath, path):
      echo "VIOLATION: ", outputPath, " source_hash mismatch (regenerate required)"
      inc violations
      continue

    let feature = compileScenario(path)
    createDir(outputDir)
    writeFile(outputPath, feature)
    inc compiled
    echo "  Compiled: ", path, " → ", outputPath

  if violations > 0:
    echo "FAIL: ", violations, " immutability violation(s) detected"
    quit(1)

  echo "OK: ", compiled, " scenario(s) compiled"

when isMainModule:
  main()
